complexParameter.core:text:
// --- helpers -------------------------------------------------------------
// SANDBOX-SAFE ONLY: hale studio runs Groovy sandboxed unless the project is
// trusted. The sandbox rejects `instanceof`, `=~` and `in`, and forbids calling
// `equals` on some hale classes (so never `== null` against a CRS object). Do
// not reintroduce them - the failure takes down the whole type cell (9.10).
def val = { p -> try { p?.value() } catch (e) { null } }
def str = { p -> def x = val(p); (x == null || x.toString().isEmpty()) ? null : x.toString() }
// GeoPackage DATETIME binds to java.time.Instant, whose toString() is already
// ISO-8601 UTC - exactly what xs:dateTime wants. Pass the raw value through and
// let hale convert it, the same way the native Rename cells do.
def num = { p -> val(p) }
// GeoPackage DATETIME columns usually bind to java.time.Instant, whose
// toString() is already ISO-8601 UTC. But the column is TEXT under the hood and
// a GeoPackage may hold e.g. "2018-01-02 00:00:00" (space, no zone), which is
// NOT a valid xs:dateTime and would be written through verbatim. Normalise.
// Sandbox-safe: no instanceof, no regex, no `in`.
def dt = { p ->
  def x = val(p)
  if (x == null) return null
  def t = x.toString().trim()
  if (t.isEmpty()) return null
  t = t.replace(' ', 'T')
  if (!t.contains('T')) t = t + 'T00:00:00'
  def tail = t.length() > 11 ? t.substring(11) : ''
  if (!t.endsWith('Z') && !tail.contains('+') && !tail.contains('-')) t = t + 'Z'
  return t
}
def bool = { p -> def x = val(p); x == null ? null : ['1', 'true', 'TRUE'].contains(x.toString()) }
def gid = { pre, g -> pre + '_' + g }
def ref = { pre, g -> '#' + pre + '_' + g }
def SO_NS = 'http://inspire.ec.europa.eu/schemas/so/4.0'
// AXIS ORDER. EPSG:3035 declares northing first, a GeoPackage stores easting
// first, and hale's GML writer emits JTS (x, y) verbatim without consulting the
// CRS (docs/hale-axis-order.md). Until hale honours axis order natively, the
// swap is done here so the pipeline stays hale-only: reflecting about y=x
// exchanges the ordinates. NOTE this puts transposed geometry into hale's
// instance model - the GUI preview will show it mirrored, and the writer must
// therefore run with -Sgeometry.unifyWindingOrder clockwise, because reflecting
// reverses ring orientation. Remove all of this once hale can do it.
def swapGeom = { gp ->
  if (gp == null) return null
  def g = gp.geometry
  if (g == null) return null
  // copy() so the source instance is never mutated; the filter then exchanges
  // x and y on every coordinate of every geometry type (Point, Polygon,
  // MultiPolygon, ...), and geometryChanged() drops the cached envelope.
  def out = g.copy()
  out.apply({ c -> def t = c.x; c.x = c.y; c.y = t } as org.locationtech.jts.geom.CoordinateFilter)
  out.geometryChanged()
  new eu.esdihumboldt.hale.common.instance.geometry.DefaultGeometryProperty(
      gp.getCRSDefinition(), out)
}

// --- texture -> so:particleSizeFraction ------------------------------------
// Texture observations (sand / silt / clay) have no INSPIRE parameter-name value;
// INSPIRE models them as particleSizeFraction, not as observations.
def GLOSIS_NS = 'http://w3id.org/glosis/model/codelists/'
def TEXTURE = [
  'textClayPropertyCode-Cl': [0, 2],
  'textSandPropertyCode-Sa_ISO': [63, 2000],
  'textSandPropertyCode-Sa_ISSS': [20, 2000],
  'textSandPropertyCode-Sa_USDA': [50, 2000],
  'textSandPropertyCode-cSa_ISO': [630, 2000],
  'textSandPropertyCode-cSa_ISSS': [200, 2000],
  'textSandPropertyCode-cSa_USDA': [500, 1000],
  'textSandPropertyCode-fSa_ISO': [63, 200],
  'textSandPropertyCode-fSa_ISSS': [20, 200],
  'textSandPropertyCode-fSa_USDA': [100, 250],
  'textSandPropertyCode-mSa_ISO': [200, 630],
  'textSandPropertyCode-mSa_ISSS': [200, 630],
  'textSandPropertyCode-mSa_USDA': [250, 500],
  'textSandPropertyCode-vcSa_ISSS': [1250, 2000],
  'textSandPropertyCode-vcSa_USDA': [1000, 2000],
  'textSandPropertyCode-vfSa_ISSS': [63, 125],
  'textSandPropertyCode-vfSa_USDA': [50, 100],
  'textSiltPropertyCode-Si_ISO': [2, 63],
  'textSiltPropertyCode-Si_ISSS': [2, 20],
  'textSiltPropertyCode-Si_USDA': [2, 50],
  'textSiltPropertyCode-cSi_ISO': [20, 63],
  'textSiltPropertyCode-cSi_USDA': [20, 50],
  'textSiltPropertyCode-fSi_ISO': [2, 6.3],
  'textSiltPropertyCode-fSi_USDA': [2, 20],
  'textSiltPropertyCode-mSi_ISO': [6.3, 20]
]
// GLOSIS observed property -> INSPIRE parameter-name value (PARAM_MAP in the
// generator), applied only when the project variable INSPIRE_PARAMETER_NAMES is
// 'true'. Default: the external vocabulary URI is kept as stored.
def USE_INSPIRE_PARAMS = (_project.vars.INSPIRE_PARAMETER_NAMES ?: 'false').toString() == 'true'
def PARAM_MAP = [
  'physioChemicalPropertyCode-Carorg': 'organicCarbonContent',
  'physioChemicalPropertyCode-Nittot': 'nitrogenContent',
  'physioChemicalPropertyCode-pH': 'pHValue'
]
// UCUM unit code -> factor to percent (w/w); 1 dag/kg == 1 % by mass. A unit not
// listed here gives null, and the observation then stays an ordinary observation.
def PCT = ['dag/kg': 1.0, '%': 1.0, 'g/100g': 1.0, 'cg/g': 1.0, 'g/kg': 0.1,
           'mg/g': 0.1, 'kg/kg': 100.0, 'g/g': 100.0]
// The unit is the UCUM CODE, i.e. datastream.code_unitofmeasure (the FK into
// unitofmeasure.code) - not unitofmeasure.symbol, which is display text: 'pH'
// instead of '[pH]', and symbols such as 'Bq ' (trailing space) or 'dm²/m²' are
// not valid gml:UomIdentifier values.
//
// The datastream CHECK requires a unit for 'Quantity' and forbids one for
// 'Count', so a count is dimensionless: UCUM '1'. Any other type without a unit
// cannot pass the CHECK; uomOf gives null and the row is reported, not mapped.
def uomOf = { ds ->
  def u = str(ds.p.code_unitofmeasure)
  u != null ? u : (str(ds.p.type) == 'Count' ? '1' : null)
}
// Observed-property URI of an observation (its datastream's), or null.
def opOf = { e ->
  def op = e.ds.links.observedproperty.first()
  op == null ? null : str(op.p.definition)
}
// [percent, lowerUm, upperUm] for a texture observation, else null.
def texFraction = { e ->
  def d = opOf(e)
  if (d == null || !d.startsWith(GLOSIS_NS)) return null
  def r = TEXTURE[d.substring(GLOSIS_NS.length())]
  if (r == null) return null
  def f = PCT[uomOf(e.ds)]
  def v = num(e.o.p.result_real)
  if (f == null || v == null) return null
  [v * f, r[0], r[1]]
}

def guid = str(_source.p.guid)
// soilprofile.location is UNIQUE, so a plot has at most one observed profile.
def _prof = []
_source.links.soilprofile.each { p -> def g = str(p.p.guid); if (g) _prof << g }
_target {
  id(gid('SoilPlot', guid))

  inspireId {
    Identifier {
      localId(str(_source.p.inspireid_localid) ?: guid)
      // Source value first; the INSPIRE_NAMESPACE project variable (declared in the
      // .halex) only supplies a value when the source row has none.
      namespace(str(_source.p.inspireid_namespace) ?: (_project.vars.INSPIRE_NAMESPACE ?: 'https://soilwise-he.eu/'))
      def _vid = str(_source.p.inspireid_versionid); if (_vid) versionId(_vid)
    }
  }

  def gm = swapGeom(val(_source.p.soilplotlocation))
  if (gm) soilPlotLocation { Point(gm) }
  else _log.error('SoilPlot ' + guid + ': no location - mandatory and not voidable')
  soilPlotType { href(str(_source.p.soilplottype)) }

  beginLifespanVersion(dt(_source.p.beginlifespanversion))
  def _els = dt(_source.p.endlifespanversion); if (_els) endLifespanVersion(_els)

  // [1..1], nillable
  if (_prof.isEmpty()) observedProfile { nilReason('unknown') }
  else observedProfile { href(ref('SoilProfile', _prof[0])) }
  // [0..1]: omitted, not voided, when the plot is on no site
  def _site = str(_source.p.locatedon)
  if (_site) locatedOn { href(ref('SoilSite', _site)) }
}

