def guid = str(_source.p.guid)
def fao = _source.links.faohorizonnotationtype.first()
def _m = fao == null ? null : str(fao.p.faohorizonmaster_1)
def _fp = fao == null ? null : str(fao.p.faoprime)
// TRANSITIONAL HORIZONS. CREA stores the second master symbol of a transitional
// horizon (WRB Section 10.3) in faohorizonmaster_2, but FAOHorizonMaster is [1..1]
// over single letters. FAOHorizonMaster carries the first symbol, and - as agreed
// with CREA (2026-10) - the full notation goes into gml:description.
def _m2 = fao == null ? null : str(fao.p.faohorizonmaster_2)
def _sym = { u -> u.substring(u.lastIndexOf('/') + 1) }
def _desc = (_m && _m2) ? ('Transitional horizon ' + _sym(_m) + _sym(_m2)
    + ' (FAO master symbols ' + _sym(_m) + ' and ' + _sym(_m2) + ')') : null

def _obs = []
def _nonNumeric = 0
_source.links.datastream.each { ds ->
  ds.links.observation.each { o ->
    if (val(o.p.result_real) == null) { _nonNumeric++; return }
    if (uomOf(ds) == null) {
      _log.warn('Observation ' + str(o.p.guid) + ': datastream ' + str(ds.p.guid)
          + ' has no unit of measure - not mapped (gml:measure requires a uom)')
      return
    }
    _obs << [ds: ds, o: o]
  }
}
if (_nonNumeric > 0)
  _log.warn(guid + ': ' + _nonNumeric + ' non-numeric observation(s) not mapped'
      + ' (Category/Text/Boolean results have no encoding in this alignment)')
def _texCount = [:]
_obs.each { e -> if (texFraction(e) != null) { def k = opOf(e); _texCount[k] = (_texCount[k] ?: 0) + 1 } }
_texCount.each { k, n ->
  if (n > 1) _log.warn(guid + ': ' + n + ' observations of ' + k
      + ' - kept as observations, not collapsed into particleSizeFraction')
}
def _asFraction = { e -> texFraction(e) != null && _texCount[opOf(e)] == 1 }

_target {

  id(gid('ProfileElement', guid))
  // gml:description comes first in the XSD sequence; only horizons set _desc.
  if (_desc) description(_desc)

  inspireId {
    Identifier {
      localId(str(_source.p.inspireid_localid) ?: guid)
      // Source value first; the INSPIRE_NAMESPACE project variable (declared in the
      // .halex) only supplies a value when the source row has none.
      namespace(str(_source.p.inspireid_namespace) ?: (_project.vars.INSPIRE_NAMESPACE ?: 'https://soilwise-he.eu/'))
      def _vid = str(_source.p.inspireid_versionid); if (_vid) versionId(_vid)
    }
  }

  // particleSizeFraction is mandatory [1..*] and voidable. The GeoPackage holds
  // texture as observations (sand / silt / clay, ...); those become fractions
  // here and are left out of the observations. No texture -> void.
  def _psf = []
  _obs.each { e -> if (_asFraction(e)) _psf << texFraction(e) }
  if (_psf.isEmpty()) particleSizeFraction { nilReason('other:unpopulated') }
  else _psf.each { f ->
    particleSizeFraction {
      ParticleSizeFractionType {
        fractionContent(f[0] as Double)
        fractionParticleSizeRange {
          RangeType {
            upperValue(f[2] as Double)
            lowerValue(f[1] as Double)
            uom { uom('um') }
          }
        }
      }
    }
  }
  profileElementDepthRange {
    RangeType {
      def _u = num(_source.p.profileelementdepthrange_uppervalue)
      def _l = num(_source.p.profileelementdepthrange_lowervalue)
      if (_u != null) upperValue(_u as Double)
      if (_l != null) lowerValue(_l as Double)
      uom { uom('cm') }
    }
  }

  beginLifespanVersion(dt(_source.p.beginlifespanversion))
  def _els = dt(_source.p.endlifespanversion); if (_els) endLifespanVersion(_els)

  _obs.each { e ->
    def ds = e.ds
    def obs = e.o
    def _op = ds.links.observedproperty.first()
    def _pr = ds.links.observingprocedure.first()

    // Texture is emitted as so:particleSizeFraction on the profile element, not here.
    if (_asFraction(e)) return

    def _uom = uomOf(ds)
    def og = str(obs.p.guid)
    profileElementObservation {
      OM_Observation {
        id('OBS_' + og)
        // A phenomenon time with an end is a period, not an instant. The
        // GeoPackage CHECK pairs phenomenontime_start/end, so both or neither.
        def _ps = dt(obs.p.phenomenontime_start)
        def _pe = dt(obs.p.phenomenontime_end)
        phenomenonTime {
          if (_pe) {
            TimePeriod { id('PT_' + og); beginPosition(_ps); endPosition(_pe) }
          } else {
            TimeInstant { id('PT_' + og); timePosition(_ps) }
          }
        }
        // om:resultTime is [1..1] and NOT nillable, so an unknown result time is
        // gml:timePosition/@indeterminatePosition, never an empty element or a
        // bare nilReason (concept 9.17).
        def _rt = dt(obs.p.resulttime)
        if (_rt) resultTime { TimeInstant { id('RT_' + og); timePosition(_rt) } }
        else resultTime { TimeInstant { id('RT_' + og)
          timePosition { indeterminatePosition('unknown') } } }
        def _p = _pr == null ? null : str(_pr.p.definition)
        if (_p) procedure { href(_p) } else procedure { nilReason('unknown') }
        def _o = _op == null ? null : str(_op.p.definition)

        // GLOSIS -> INSPIRE parameter-name value, only if INSPIRE_PARAMETER_NAMES.
        if (USE_INSPIRE_PARAMS && _o != null && _o.startsWith(GLOSIS_NS)) {
          def _im = PARAM_MAP[_o.substring(GLOSIS_NS.length())]
          if (_im) _o = 'http://inspire.ec.europa.eu/codelist/ProfileElementParameterNameValue/' + _im
        }

        if (_o) observedProperty { href(_o) }
        else observedProperty { nilReason('unknown') }
        featureOfInterest { href(ref('ProfileElement', guid)) }
        def _v = num(obs.p.result_real)
        result { measure(_v as Double) { uom(_uom) } }
      }
    }
  }

  isPartOf { href(ref('SoilProfile', str(_source.p.ispartof))) }
  // FAOHorizonMaster and FAOPrime are [1..1] and NOT voidable, so a notation
  // missing either is voided at the voidable PARENT (xsi:nil, as WRBSoilName is)
  // instead of a nilReason on the child, as v1 did.
  if (fao == null) {
    FAOHorizonNotation { nilReason('unknown') }
  } else if (!_m || !_fp) {
    FAOHorizonNotation { nilReason('unknown') }
    _log.warn('Horizon ' + guid + ': FAO notation without master or prime symbol - voided')
  } else {
    FAOHorizonNotation {
      FAOHorizonNotationType {
        def _d = num(fao.p.faohorizondiscontinuity)
        if (_d != null) FAOHorizonDiscontinuity(_d as Integer)
        FAOHorizonMaster { href(_m) }
        FAOPrime { href(_fp) }
        ['faohorizonsubordinate_1', 'faohorizonsubordinate_2', 'faohorizonsubordinate_3'].each { c ->
          def _s = str(fao.p."$c"); if (_s) FAOHorizonSubordinate { href(_s) }
        }
        def _v = num(fao.p.faohorizonvertical)
        if (_v != null) FAOHorizonVertical(_v as Integer)
        isOriginalClassification(bool(fao.p.isoriginalclassification) ?: false)
      }
    }
    // faohorizonmaster_2 has no target here; it is carried in gml:description
    // (_desc, above).
  }
  // so:otherHorizonNotation [0..*] via the otherhorizon_profileelement junction
  _source.links.otherhorizon_profileelement.each { oh ->
    def n = oh.links.otherhorizonnotationtype.first()
    if (n == null) return
    def _hn = str(n.p.horizonnotation)
    if (_hn) otherHorizonNotation {
      OtherHorizonNotationType {
        horizonNotation { href(_hn) }
        isOriginalClassification(bool(n.p.isoriginalclassification) ?: false)
      }
    }
  }
}

