// a GeoPackage may hold e.g. "2018-01-02 00:00:00" (space, no zone), which is
// NOT a valid xs:dateTime and would be written through verbatim. Normalise.
// Sandbox-safe: no instanceof, no regex, no `in`.
def dt = { p ->
  def x = val(p)
  if (x == null) return null
  def t = x.toString().trim()
  if (t.isEmpty()) return null
  t = t.replace(' ', 'T')
  if (!t.contains('T')) t = t + 'T00:00:00'
  def tail = t.length() > 11 ? t.substring(11) : ''
  if (!t.endsWith('Z') && !tail.contains('+') && !tail.contains('-')) t = t + 'Z'
  return t
}
def bool = { p -> def x = val(p); x == null ? null : ['1', 'true', 'TRUE'].contains(x.toString()) }
def gid = { pre, g -> pre + '_' + g }
def ref = { pre, g -> '#' + pre + '_' + g }
def SO_NS = 'http://inspire.ec.europa.eu/schemas/so/4.0'
// AXIS ORDER. EPSG:3035 declares northing first, a GeoPackage stores easting
// first, and hale's GML writer emits JTS (x, y) verbatim without consulting the
// CRS (docs/hale-axis-order.md). Until hale honours axis order natively, the
// swap is done here so the pipeline stays hale-only: reflecting about y=x
// exchanges the ordinates. NOTE this puts transposed geometry into hale's
// instance model - the GUI preview will show it mirrored, and the writer must
// therefore run with -Sgeometry.unifyWindingOrder clockwise, because reflecting
// reverses ring orientation. Remove all of this once hale can do it.
def swapGeom = { gp ->
  if (gp == null) return null
  def g = gp.geometry
  if (g == null) return null
  // copy() so the source instance is never mutated; the filter then exchanges
  // x and y on every coordinate of every geometry type (Point, Polygon,
  // MultiPolygon, ...), and geometryChanged() drops the cached envelope.
  def out = g.copy()
  out.apply({ c -> def t = c.x; c.x = c.y; c.y = t } as org.locationtech.jts.geom.CoordinateFilter)
  out.geometryChanged()
